"""Tests for tasks_api.models."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTag:
    def test_normalizes_to_lowercase(self):
        assert Tag("Hello").name == "hello"

    def test_strips_whitespace(self):
        assert Tag("  foo  ").name == "foo"

    def test_rejects_empty(self):
        with pytest.raises(ValueError):
            Tag("")

    def test_rejects_whitespace_only(self):
        with pytest.raises(ValueError):
            Tag("   ")

    def test_rejects_non_string(self):
        with pytest.raises(TypeError):
            Tag(123)  # type: ignore[arg-type]

    def test_rejects_too_long(self):
        with pytest.raises(ValueError):
            Tag("a" * 33)

    def test_rejects_illegal_character(self):
        with pytest.raises(ValueError):
            Tag("hello world")

    def test_allows_hyphen_and_underscore(self):
        assert Tag("my-tag_1").name == "my-tag_1"


class TestTaskPriority:
    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)


class TestTaskIsOverdue:
    def test_not_overdue_when_no_due_date(self):
        task = Task(id=1, title="t")
        assert task.is_overdue(datetime.now(timezone.utc)) is False

    def test_not_overdue_when_done(self):
        task = Task(id=1, title="t", status=TaskStatus.DONE, due_at=datetime(2020, 1, 1, tzinfo=timezone.utc))
        assert task.is_overdue(datetime.now(timezone.utc)) is False

    def test_overdue_when_due_in_past(self):
        task = Task(id=1, title="t", due_at=datetime(2020, 1, 1, tzinfo=timezone.utc))
        assert task.is_overdue(datetime(2025, 1, 1, tzinfo=timezone.utc)) is True

    def test_not_overdue_when_due_in_future(self):
        task = Task(id=1, title="t", due_at=datetime(2099, 1, 1, tzinfo=timezone.utc))
        assert task.is_overdue(datetime(2025, 1, 1, tzinfo=timezone.utc)) is False

